class PlaceOrderService
  def initialize(customers:, orders:, outbox:)
    @customers, @orders, @outbox = customers, orders, outbox
  end

  def call(cmd)
    ActiveRecord::Base.transaction do           # commits on exit, rolls back on raise
      customer = @customers.of_id(cmd.customer_id)
      order = customer.place_order(cmd.items)   # the aggregate decides
      @orders.add(order)
      @outbox.record(order.pending_events)      # durable outbox row, not a remote publish
      order.id
    end
  end
end
